import json,html
from pathlib import Path
R=Path(__file__).parent; data=json.loads((R/'results.json').read_text()); S=data['summary']
slides=[
('Paměť agenta: co uložit, co vybavit','30 minut • workshop pro vývojáře', ['Cíl: zvolit strukturu podle otázky a rozpočtu kontextu.','Budeme předpovídat výsledky, procházet důkazy a měnit top‑k.','Paměť zde = uložená data + pravidla zápisu + vybavení do promptu.'], '0–2 min: hlasování. Kde dnes držíte paměť: historie, summary, SQL, vektory, graf? Vyberte jednu zkušenost účastníka.'),
('Tři různé rozpočty','Nezaměňujme kontext, úložiště a RAM', ['Kontext LLM: tokeny vybraných důkazů a instrukcí.','Úložiště: původní text + metadata + embeddingy / hrany.','RAM a latence: index, cache, retrieval, případně model.','Menší retrieval neznamená automaticky správnější odpověď.'], '2–4 min: ukažte cestu událost → zápis → index → retrieval → prompt. V našem měření počítáme UTF‑8 bajty, nikoli tokeny. KV cache je jiná vrstva optimalizace.'),
('Menu struktur','Paměť není jen databáze', ['Okno historie: přesné nedávné události; staré informace vypadnou.','Summary: krátký přehled; při kompresi může zmizet podmínka či zdroj.','JSON / SQL: aktuální stav, preference, verze a přesné filtry.','Episody + vektory: podobné zkušenosti a neformální text.','Knowledge Graph: entity, typované vztahy, cesty a provenience.'], '4–6 min: preference uživatele patří do stavu, incident do epizody, závislost do vztahu. Stejný záznam lze indexovat několika způsoby. Procedurální paměť = ověřené postupy/runbooky; sémantická = fakta; epizodická = události.'),
('Stejná data, jiné otázky','Tři provozní úlohy', ['A • Jak se řešil podobný connection-pool timeout?','B • Na čem svc-0 závisí a který tým eskalovat?','C • Kdo je aktuální vlastník svc-0 po migraci?','Tipněte si: vektor, graf, nebo přesný stav?'], '6–8 min: dejte 30 sekund ve dvojicích. Jde o realistické, ale syntetické scénáře, nikoli záznamy skutečného incidentu. Každý typ má osm variant.'),
('Knowledge Graph × vektorový index','Podobnost není vztah', ['Vektor: dotaz → podobné texty → top‑k. Přirozený text, parafráze, epizody.','Graf: entita → typované hrany → sousedé / cesty. Vazby, dopady, zdroje.','Vektor potřebuje metadata pro čas, tenant a autoritu.','Graf potřebuje extrakci, sjednocení entit a správné směry hran.','Obě varianty mohou používat stejné SQL úložiště.'], '8–10 min: ukažte diagram svc-0 → db-0 → team-0. Druhá hrana neobsahuje svc-0; textová podobnost nemá důvod ji vrátit. GraphRAG je širší rodina postupů, ne synonymum pro každý graf.'),
('Živá ukázka: najdi chybějící hranu','Nejdřív tip, potom důkazy', ['Otevřete ukázku níže nebo demo.html.','Zvolte B a porovnejte vector s graph.','Zvolte A: samotný graf nemá vyhledávač epizod.','Skutečný kód: source-demo.html — import → reexport → normalize.'], '10–15 min: A 90 s, B 90 s, skutečný kód 2 min (source-demo.html); C volitelně po meetingu. U B ukažte očekávané ID i chybějící ID. C není kompletní temporal engine: aktuální stav je ručně materializovaný. Nezavádějte žádné API klíče, vše běží offline.'),
('Jak jsme měřili','Retrieval, nikoli inteligenci agenta', ['48 dokumentů • 24 dotazů • top‑k = 2 • 50 opakování/dotaz.','Gold = ručně určená ID potřebných důkazů.','Úplnost = vráceny všechny gold dokumenty; recall = podíl gold.','Precision = podíl relevantních dokumentů mezi vrácenými.','Kontext = UTF‑8 bajty; čas = warm retrieval v procesu.'], '15–17 min: celé tělo textu je vraceno, žádné ořezávání do stejného budgetu. full má neomezený kontext. Dotazy sdílejí šablony: 24 není 24 nezávislých problémů. Latence neobsahuje LLM, síť, ingest ani klasifikaci dotazu.'),
('Vlastní výsledky','Jeden běh; reprodukovatelné v results.json', [f"{x['method']}: úplné důkazy {x['complete']}/24 · průměr {x['context_bytes']} B" for x in S], '17–19 min: ukažte graf a důkazy. Hybrid vrací asi o 96 % méně bajtů než full, ale data i routování jsou idealizované. Čísla nepřenášet na produkční vector DB / graph DB. Grafové cesty jsou dictionary lookup, vektory sparse exact cosine, ne ANN.'),
('Změňme top‑k','Více textu může pomoci, ale také zaplnit prompt', [f"k={x['k']}: úplné důkazy {x['complete']}/24 · {x['context_bytes']} B" for x in data['sweep']], '19–21 min: před odhalením tipněte, zda k=8 opraví B. Všechny hodnoty jsou skutečně změřené nad stejnými daty. Zvyšování k není náhradou za návaznost vztahů a časové filtry.'),
('Hybrid: oddělte text, stav a vazby','Orchestrace je část ceny', ['Ulož událost se source_id, entity_id, valid_from/to a autoritou.','SQL / JSON: aktuální stav; graf: vztahy; vektory: epizody.','Dotaz → intent + entity → retrieval → deduplikace → budget.','Ke každému důkazu připoj zdroj, čas a verzi.','Při konfliktu zdrojů ukaž nejistotu, nedělej tichý overwrite.'], '21–24 min: v našem hybridu známe intent a entity ze zadání. V produkci změřte chyby routeru, extrakce i entity resolution; graf nevymyslí chybějící hranu. Aktualizace vlastníka má uzavřít valid_to starého tvrzení, zachovat audit a invalidovat cache.'),
('Cvičení: návrh paměti pro vašeho agenta','Dvě minuty ve dvojicích', ['Agent si pamatuje preference, incidenty a vlastníky služeb.','Má vracet nejvýše 1 000 tokenů důkazů.','Navrhněte zápis, retrieval a chování při změně vlastníka.','Jakým dotazem zjistíte, že návrh selhal?'], '24–27 min: 2 min práce + 1 min dvě odpovědi. Očekávané řešení: preference přesný stav, incidenty epizody, vlastnictví verzované vztahy/stav. Test: historický vlastník k datu, nezáměnné identifikátory, konflikt zdrojů, tenant isolation.'),
('Rozhodnutí a další experiment','Začněte otázkami, které agent musí zvládnout', ['Podobné zkušenosti → textové / vektorové hledání.','Přesná fakta a aktuální hodnoty → SQL / JSON + časové filtry.','Více vazeb a dopady → graf, pokud máte kvalitní entity a hrany.','Kombinujte jen tam, kde testy ukážou přínos.','Produkčně měřte odpovědi, tokeny, p95, ingest a cenu aktualizací.'], '27–30 min: 2 min otázky, 1 min závěr. Vyberte 20 skutečných dotazů vašeho týmu a porovnejte na stejném token budgetu: lexical, neural, SQL, graph a hybrid. Předem definujte gold, validitu, abstenci a náklady. Na 30 min skončete.')]
(R/'slides.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2))
css='''*{box-sizing:border-box}body{margin:0;background:#101728;color:#f0f4ff;font:20px system-ui}main{max-width:1200px;margin:auto;padding:36px}h1{font-size:48px;line-height:1.12;margin:10px 0 18px}h2{color:#75dfc8;font-size:25px}li{margin:18px 0;line-height:1.4}.slide{display:none;min-height:72vh}.slide.on{display:block}button,select{background:#23334d;color:white;border:1px solid #7587a4;padding:12px;border-radius:8px;font:inherit;margin:5px;cursor:pointer}button:hover{background:#345078}nav{display:flex;align-items:center;gap:12px;flex-wrap:wrap}small,.muted{color:#a9bbd6}details{margin:20px 0;font-size:16px}pre{white-space:pre-wrap;font:15px ui-monospace;background:#18243b;padding:15px;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:18px}td,th{text-align:left;border-bottom:1px solid #354561;padding:10px}svg{width:100%;max-height:230px}a{color:#75dfc8}@media print{body{background:white;color:black}.slide{display:block!important;min-height:0;break-after:page}nav,.demo,details{display:none}main{padding:0}h1{font-size:32px}li{font-size:20px}small{color:#444}}'''
graph='''<svg viewBox="0 0 1000 160" role="img" aria-label="svc-0 depends_on db-0 owned_by team-0"><defs><marker id="a" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#75dfc8"/></marker></defs><g fill="#23334d" stroke="#75dfc8"><rect x="20" y="60" width="170" height="70" rx="12"/><rect x="400" y="60" width="170" height="70" rx="12"/><rect x="790" y="60" width="170" height="70" rx="12"/><path d="M190 95H390 M570 95H780" marker-end="url(#a)"/></g><g fill="white" font-size="24" text-anchor="middle"><text x="105" y="104">svc-0</text><text x="485" y="104">db-0</text><text x="875" y="104">team-0</text><text x="285" y="60">depends_on</text><text x="675" y="60">owned_by</text></g></svg>'''
def demo():return '''<div class="demo"><p>Uložené výsledky skutečného běhu. Ovládání mění zobrazení; nový benchmark spustíte v Pythonu.</p><label>Otázka <select id="q"><option value="q-inc-0">A: podobný incident</option><option value="q-path-0">B: závislost a eskalace</option><option value="q-now-0">C: aktuální vlastník</option></select></label><label>Metoda <select id="m"><option>vector</option><option>graph</option><option>hybrid</option><option>full</option></select></label><button onclick="show()">Odhalit důkazy</button><pre id="out" aria-live="polite">Nejdřív tipněte výsledek.</pre></div>'''
parts=[]
for i,(title,sub,bullets,note) in enumerate(slides):
 extra=graph if i==4 else '<p><a href="source-demo.html" target="_blank">Skutečný kód scikit-learn: odhalit importní řetězec ↗</a></p>'+demo() if i==5 else ''
 if i==7:
  extra='<table><tr><th>Metoda</th><th>Úplnost</th><th>Recall</th><th>Precision</th><th>ms*</th></tr>'+''.join(f"<tr><td>{x['method']}</td><td>{x['complete']}/24</td><td>{x['recall']:.2f}</td><td>{x['precision']:.2f}</td><td>{x['latency_median_ms']:.6f}</td></tr>" for x in S)+'</table><small>* Medián mediánů na dotaz; in-process, bez plánování.</small>'
 parts.append(f'<section class="slide {"on" if i==0 else ""}"><small>LLM MEMORY LAB • {i+1:02}/12</small><h1>{html.escape(title)}</h1><h2>{html.escape(sub)}</h2><ul>'+''.join(f'<li>{html.escape(b)}</li>' for b in bullets)+f'</ul>{extra}<details><summary>Poznámky moderátora</summary>{html.escape(note)}</details></section>')
js='''let n=0;const slides=[...document.querySelectorAll('.slide')];function move(d){n=Math.max(0,Math.min(slides.length-1,n+d));slides.forEach((s,i)=>s.classList.toggle('on',i===n));document.getElementById('page').textContent=(n+1)+' / '+slides.length;}document.addEventListener('keydown',e=>{if(['SELECT','BUTTON'].includes(e.target.tagName))return;if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1);});function show(){const row=DATA.rows.find(r=>r.query===document.getElementById('q').value&&r.method===document.getElementById('m').value);const docs=row.retrieved.map(id=>DATA.documents.find(d=>d.id===id));document.getElementById('out').textContent='Gold: '+row.gold.join(', ')+'\\nVráceno: '+row.retrieved.join(', ')+'\\nÚplné důkazy: '+(row.complete?'ANO':'NE')+' | Recall: '+row.recall+' | Kontext: '+row.context_bytes+' B\\n\\n'+docs.map(d=>d.id+': '+d.text).join('\\n\\n');}'''
(R/'presentation.html').write_text('<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paměť LLM agenta · workshop</title><style>'+css+'</style><main>'+''.join(parts)+'<nav><button onclick="move(-1)">← Zpět</button><span id="page">1 / 12</span><button onclick="move(1)">Dále →</button><button onclick="document.documentElement.requestFullscreen()">Celá obrazovka</button><button onclick="window.print()">PDF / tisk</button></nav></main><script>const DATA='+json.dumps(data)+';'+js+'</script></html>')
# standalone demo uses only the independent show function
(R/'demo.html').write_text('<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Retrieval: důkazy</title><style>'+css+'</style><main><h1>Kam zmizela druhá hrana?</h1>'+graph+demo()+'<p><a href="presentation.html">Prezentace</a> · <a href="results.json">Naměřená data</a></p></main><script>const DATA='+json.dumps(data)+';function show()'+js.split('function show()')[1]+'</script></html>')
notes='# Scénář moderátora — 30 minut\n\nPříprava: otevřít presentation.html a demo.html; není potřeba internet. Připravit Python pouze pro přepočet benchmarku. Účastníci nemusí nic instalovat.\n\n'+ '\n\n'.join(f'## {i+1}. {s[0]}\n\n{s[3]}' for i,s in enumerate(slides))
notes+='''\n\n## Záchranný scénář\n\nPři problému s prohlížečem použijte PDF/PPTX a results.csv. Demo je předpočítané, ne živý volaný LLM. Pokud dojde čas, přeskočte sweep a zkraťte návrhové cvičení na hlasování; konec nejpozději ve 30:00.\n\n## Otázky a odpovědi\n\n- Graf vždy lepší? Ne; u podobných incidentů zde nemá žádný mechanismus retrievalu. Lze ho doplnit fulltextem či vektory.\n- Proč ne neuronové embeddingy? Základní ukázka funguje offline a izoluje strukturu retrievalu. TF‑IDF je lexical vektorová reprezentace, ne test parafrází.\n- Proč je graf tak rychlý? Ruční dictionary lookup nad miniaturními daty, bez query planneru a sítě. Nejde o srovnání výkonu databázových produktů.\n- Co s chybnou hranou? Vyžadovat zdroj, validitu, schema validation, rozlišení entit a testy aktualizací. Měřit i přesnost extrakce.\n- Optimalizujeme RAM? Přímo měříme jen sparse matici indexu a délku kontextu, ne kompletní RAM. K tomu je potřeba izolované měření RSS, stejný korpus a oba reálné DB procesy.\n- Jak ověřit odpovědi LLM? Stejný prompt/model/teplota a token budget, gold odpovědi, citace, abstence, několik běhů a slepé hodnocení.\n'''
(R/'facilitator.md').write_text(notes)
